  if(normalized==='UNIVERSAL_ACCESS_EXPIRED')return(ACCESS_ERROR_COPY[state.locale]||ACCESS_ERROR_COPY.en).expired;
  const invalidCodes=new Set(['UNIVERSAL_UID_REQUIRED','UNIVERSAL_RUNTIME_NOT_FOUND','UNIVERSAL_ACCESS_UNAVAILABLE','UNIVERSAL_ACCESS_NOT_PLATFORM_MANAGED','UNIVERSAL_TOKEN_INVALID','UNIVERSAL_TOKEN_SCOPE_INVALID','UNIVERSAL_TOKEN_UID_MISMATCH','UNIVERSAL_TOKEN_COMPANY_MISMATCH','UNIVERSAL_TOKEN_ACCESS_MISMATCH','UNIVERSAL_TOKEN_NONCE_MISMATCH']);
