async function bootstrap(){if(!state.uid)return fail({code:'UNIVERSAL_UID_REQUIRED',message:t('unavailableText')});try{const data=await api('v2AppBootstrap',{method:'GET',query:{uid:state.uid,userAgent:navigator.userAgent,deviceClass:deviceClass()}});state.payload=data;state.token=data.token||'';state.participantLocale=normalizeUiLocale(data.runtime?.participantLang||data.runtime?.userCommLang||'en');state.locale=state.participantLocale;state.module=resolveModuleView(data,state.locale);prefill();applyLocale();await applyBranding(data.branding||data.runtime?.brandingSnapshot||{});setStep('welcome');show('welcomeView');revealApp();feedbackController?.probe()}catch(e){await fail(e)}}
async function saveProfile(){const button=$('saveProfileBtn'),profile={firstName:$('firstName').value.trim(),lastName:$('lastName').value.trim(),email:$('email').value.trim(),externalReference:$('externalReference').value.trim()};if(button?.getAttribute('aria-busy')==='true')return;if(!profile.firstName||!profile.lastName||!/^\S+@\S+\.\S+$/.test(profile.email))return alert(t('profileError'));setActionBusy(button,true);try{const data=await api('v2AppProfile',{body:{token:state.token,uid:state.uid,profile}});state.payload.runtime={...state.payload.runtime,...data.runtime};setStep('consent');show('consentView')}catch(e){alert(e.message||t('genericError'))}finally{setActionBusy(button,false)}}
async function saveConsent(){const button=$('saveConsentBtn'),mediaOk=!state.module?.media||$('consentMediaRequired').checked;if(button?.getAttribute('aria-busy')==='true')return;if(!$('consentPrivacyRequired').checked||!$('consentAiRequired').checked||!mediaOk)return alert(t('consentError'));setActionBusy(button,true);try{const data=await api('v2AppConsent',{body:{token:state.token,uid:state.uid,accepted:true,privacyAccepted:true,aiInteractionAccepted:true,mediaAccepted:state.module?.media===true,version:CANDIDATE_LEGAL_VERSION,noticeLocale:state.locale,noticeUpdatedAt:CANDIDATE_LEGAL_UPDATED_AT,privacyNoticeVersion:CANDIDATE_LEGAL_VERSION,participationNoticeVersion:CANDIDATE_LEGAL_VERSION,noticeDocuments:['cookie_privacy_ai','participation_data_processing_ai']}});state.payload.runtime={...state.payload.runtime,...data.runtime};renderPayload();setStep('module');show('moduleView')}catch(e){alert(e.message||t('genericError'))}finally{setActionBusy(button,false)}}
async function refreshStatus(){const button=$('statusBtn');if(button?.getAttribute('aria-busy')==='true')return;setActionBusy(button,true);try{const data=await api('v2AppStatus',{body:{token:state.token,uid:state.uid}});state.payload={...state.payload,...data};state.module=resolveModuleView(state.payload,state.locale);renderPayload()}catch(e){alert(e.message||t('genericError'))}finally{setActionBusy(button,false)}}
async function startModule(){const button=$('startModuleBtn');if(button?.getAttribute('aria-busy')==='true')return;if(!state.module?.startEnabled)return alert(t('modulePendingAlert'));setActionBusy(button,true);feedbackController?.startMonitoring({continuous:true});try{const key=state.payload?.runtime?.productKey;if(key==='cv_analysis')await cvModule.activate();else if(key==='video_presentation')await vpModule.activate();else if(key==='ai_literacy')await aiLiteracyModule.activate();else if(['assessment','snapshot'].includes(key))await assessmentModule.activate();else if(key==='interview')await interviewModule.activate();else throw new Error(t('modulePendingAlert'));button.dataset.activationCommitted='true'}catch(e){setActionBusy(button,false);alert(e.message||t('genericError'))}}
function wire(){
  $('langBtn').addEventListener('click',()=>{state.locale=state.locale===state.participantLocale?'en':state.participantLocale;applyLocale()});$('supportBtn').addEventListener('click',()=>{location.href='mailto:info@clarity-nvl.com'});$('continueProfileBtn').addEventListener('click',()=>{setStep('profile');show('profileView')});$('backWelcomeBtn').addEventListener('click',()=>{setStep('welcome');show('welcomeView')});$('saveProfileBtn').addEventListener('click',saveProfile);$('backProfileBtn').addEventListener('click',()=>{setStep('profile');show('profileView')});$('saveConsentBtn').addEventListener('click',saveConsent);$('statusBtn').addEventListener('click',refreshStatus);$('startModuleBtn').addEventListener('click',startModule);
  document.querySelectorAll('#consentView [data-legal-document]').forEach(button=>button.addEventListener('click',()=>openLegalDocument(button.dataset.legalDocument,button)));
  $('legalTabPrivacy').addEventListener('click',()=>renderLegalDocument('privacy'));
  $('legalTabParticipation').addEventListener('click',()=>renderLegalDocument('participation'));
  $('legalDialogCloseX').addEventListener('click',closeLegalDialog);
  $('legalDialogCloseBtn').addEventListener('click',closeLegalDialog);
  $('legalDialog').addEventListener('click',event=>{if(event.target===$('legalDialog'))closeLegalDialog()});
  $('legalDialog').addEventListener('close',()=>{const target=legalReturnFocus;legalReturnFocus=null;if(target&&typeof target.focus==='function')target.focus()});
}
cvModule=createCvModule({$,state,api,show,setStep,getLocale:()=>state.locale,onFatal:fail});vpModule=createVideoPresentationModule({$,state,api,show,setStep,getLocale:()=>state.locale,onFatal:fail,refreshToken:refreshUniversalToken});aiLiteracyModule=createAiLiteracyModule({$,state,api,show,setStep,getLocale:()=>state.locale,onFatal:fail});assessmentModule=createAssessmentModule({$,state,api,show,setStep,getLocale:()=>state.locale,onFatal:fail,refreshToken:refreshUniversalToken});interviewModule=createInterviewModule({$,state,api,show,setStep,getLocale:()=>state.locale,onFatal:fail,refreshToken:refreshUniversalToken});feedbackController=createAppFeedbackController({$,state,api,getLocale:()=>state.locale,getBrandingMode:()=>resolveBrandingMode(state.payload?.branding||state.payload?.runtime?.brandingSnapshot||{})});wire();applyLocale();bootstrap();
